+// generateAppID computes Chromium's double-SHA256 App ID for a given start URL or manifest ID
+func generateAppID(manifestIDOrURL string) string {
+	h1 := sha256.Sum256([]byte(manifestIDOrURL))
+	h2 := sha256.Sum256(h1[:])
